import type { AgentStatusSlice } from './agent-status-slice-contract'
import type { AgentStatusRuntime } from './agent-status-runtime'
import { rendererAgentStatusObservations } from '../../lib/renderer-agent-status-observations'
import {
  resolveAgentPaneAuthorityKey,
  retireAgentPaneAuthorityAliases,
  transferAgentPaneAuthorityAlias
} from './agent-pane-authority'
import {
  boundRecentlyRetiredAgentStatusPaneKeys,
  movePaneKeyedRecord,
  removePaneKeys
} from './agent-status-pane-keyed-records'
import {
  getLeafIdFromPaneKey,
  getTabIdFromPaneKey,
  isRecentlyClosedAgentStatusTab
} from './agent-status-pane-key-tab-binding'
import { createBrowserUuid } from '@/lib/browser-uuid'

export function createAgentStatusAuthorityActions(
  runtime: AgentStatusRuntime
): Pick<
  AgentStatusSlice,
  | 'scheduleAgentStatusFreshness'
  | 'retireAgentPaneAuthority'
  | 'restoreAgentPaneAuthority'
  | 'transferAgentPaneAuthority'
> {
  const { get, set, freshness } = runtime
  return {
    scheduleAgentStatusFreshness: () => freshness.schedule(),

    retireAgentPaneAuthority: (paneKey, options) => {
      const retirementId = createBrowserUuid()
      const ownerPaneKey = resolveAgentPaneAuthorityKey(paneKey)
      const previousRetirement = get().recentlyRetiredAgentStatusPaneKeys[ownerPaneKey]
      const retiredPaneKeys = [
        ...new Set([
          ...retireAgentPaneAuthorityAliases(paneKey),
          ...Object.keys(get().recentlyRetiredAgentStatusPaneKeys).filter(
            (key) =>
              typeof previousRetirement === 'string' &&
              get().recentlyRetiredAgentStatusPaneKeys[key] === previousRetirement
          )
        ])
      ]
      const retiredPaneKeySet = new Set(retiredPaneKeys)
      for (const key of retiredPaneKeys) {
        rendererAgentStatusObservations.forget(key)
      }
      let hadLive = false
      set((s) => {
        const retiredLivePaneKeys = retiredPaneKeys.filter((key) => key in s.agentStatusByPaneKey)
        hadLive = retiredLivePaneKeys.length > 0
        let nextRetentionSuppressedPaneKeys = removePaneKeys(
          s.retentionSuppressedPaneKeys,
          retiredPaneKeySet
        )
        if (
          retiredLivePaneKeys.length > 0 &&
          nextRetentionSuppressedPaneKeys === s.retentionSuppressedPaneKeys
        ) {
          nextRetentionSuppressedPaneKeys = { ...nextRetentionSuppressedPaneKeys }
        }
        for (const key of retiredLivePaneKeys) {
          nextRetentionSuppressedPaneKeys[key] = true
        }
        return {
          agentStatusByPaneKey: removePaneKeys(s.agentStatusByPaneKey, retiredPaneKeySet),
          runtimeAgentOrchestrationByPaneKey: removePaneKeys(
            s.runtimeAgentOrchestrationByPaneKey,
            retiredPaneKeySet
          ),
          retainedAgentsByPaneKey: removePaneKeys(s.retainedAgentsByPaneKey, retiredPaneKeySet),
          sleepingAgentSessionsByPaneKey: options?.preserveSleepingAgentSession
            ? s.sleepingAgentSessionsByPaneKey
            : removePaneKeys(s.sleepingAgentSessionsByPaneKey, retiredPaneKeySet),
          agentLaunchConfigByPaneKey: removePaneKeys(
            s.agentLaunchConfigByPaneKey,
            retiredPaneKeySet
          ),
          acknowledgedAgentsByPaneKey: removePaneKeys(
            s.acknowledgedAgentsByPaneKey,
            retiredPaneKeySet
          ),
          activityClearedAtByPaneKey: removePaneKeys(
            s.activityClearedAtByPaneKey,
            retiredPaneKeySet
          ),
          manuallyUnreadTurnsByPaneKey: removePaneKeys(
            s.manuallyUnreadTurnsByPaneKey,
            retiredPaneKeySet
          ),
          paneForegroundAgentByPaneKey: removePaneKeys(
            s.paneForegroundAgentByPaneKey,
            retiredPaneKeySet
          ),
          unreadTerminalPanes: removePaneKeys(s.unreadTerminalPanes, retiredPaneKeySet),
          unreadAgentCompletionPanes: removePaneKeys(
            s.unreadAgentCompletionPanes,
            retiredPaneKeySet
          ),
          lastTerminalInputAtByPaneKey: removePaneKeys(
            s.lastTerminalInputAtByPaneKey,
            retiredPaneKeySet
          ),
          cacheTimerByKey: removePaneKeys(s.cacheTimerByKey, retiredPaneKeySet),
          retentionSuppressedPaneKeys: nextRetentionSuppressedPaneKeys,
          recentlyRetiredAgentStatusPaneKeys: boundRecentlyRetiredAgentStatusPaneKeys(
            s.recentlyRetiredAgentStatusPaneKeys,
            retiredPaneKeys,
            s.recentlyRetiredAgentStatusPaneKeys[ownerPaneKey] === true ||
              isRecentlyClosedAgentStatusTab(
                s.recentlyClosedAgentStatusTabIds,
                getTabIdFromPaneKey(ownerPaneKey)
              )
              ? true
              : retirementId
          ),
          agentStatusEpoch: hadLive ? s.agentStatusEpoch + 1 : s.agentStatusEpoch,
          sortEpoch: hadLive ? s.sortEpoch + 1 : s.sortEpoch
        }
      })
      if (hadLive) {
        freshness.scheduleDeferred()
      }
      if (typeof window !== 'undefined') {
        window.api?.agentStatus?.retirePaneAuthority?.(
          ownerPaneKey,
          get().recentlyRetiredAgentStatusPaneKeys[ownerPaneKey] === retirementId
            ? retirementId
            : undefined
        )
      }
    },

    // Why: the tombstone claims this pane is gone; a live PTY binding to it proves
    // otherwise. Lift the fence on that proof rather than on the next hook event —
    // a pane re-attached mid-turn or while idle emits no new-turn event, so a
    // turn-triggered revival leaves exactly the reported permanent suppression
    // (STA-4114). This deliberately does NOT restore the rows retirement dropped;
    // those are genuinely stale. It only re-opens the pane to future status.
    restoreAgentPaneAuthority: (paneKey) => {
      const ownerPaneKey = resolveAgentPaneAuthorityKey(paneKey)
      // Why: a closed tab is a stronger, separate claim — re-attach must not undo it.
      if (
        isRecentlyClosedAgentStatusTab(
          get().recentlyClosedAgentStatusTabIds,
          getTabIdFromPaneKey(ownerPaneKey)
        )
      ) {
        return
      }
      set((s) => {
        const restorable = [paneKey, ownerPaneKey].filter(
          (key) => key in s.recentlyRetiredAgentStatusPaneKeys
        )
        if (restorable.length === 0) {
          return s
        }
        const next = { ...s.recentlyRetiredAgentStatusPaneKeys }
        for (const key of restorable) {
          delete next[key]
        }
        return { recentlyRetiredAgentStatusPaneKeys: next }
      })
      // Why: deliberately OUTSIDE the guard above, and not gated on having cleared
      // anything here. This map is not a mirror of main's — main fences panes the
      // renderer never hears about (retirePtyAgentLaunchAuthority on command-finished
      // and PTY exit calls the hook server directly, and nothing pushes that back), and
      // this map is per-window and non-persisted, so a renderer reload empties it while
      // main's survives. Gating the send on a local tombstone reintroduces STA-4114 for
      // exactly those panes. The send is idempotent and main refuses closed tabs itself.
      if (typeof window !== 'undefined') {
        window.api?.agentStatus?.restorePaneAuthority?.(ownerPaneKey)
      }
    },
    transferAgentPaneAuthority: ({ fromPaneKey, toPaneKey, ptyId }) => {
      const transfer = transferAgentPaneAuthorityAlias({ fromPaneKey, toPaneKey, ptyId })
      if (!transfer || transfer.previousOwnerPaneKey === transfer.ownerPaneKey) {
        return
      }
      const from = transfer.previousOwnerPaneKey
      const to = transfer.ownerPaneKey
      // Why: the moved row carries the observation stamped for its OLD key; renderer-authored
      // observations for the new key must sort after it, not race it.
      rendererAgentStatusObservations.forget(from)
      rendererAgentStatusObservations.rebind(to)
      const targetTabId = getTabIdFromPaneKey(to) ?? undefined
      const targetLeafId = getLeafIdFromPaneKey(to) ?? undefined
      set((s) => ({
        agentStatusByPaneKey: movePaneKeyedRecord(s.agentStatusByPaneKey, from, to, (entry) => ({
          ...entry,
          paneKey: to,
          tabId: targetTabId
        })),
        // Why: retention/sidebar consumers gate on the epoch; a moved live row is a
        // pane-key change they must observe, not a silent remap.
        ...(from in s.agentStatusByPaneKey
          ? { agentStatusEpoch: s.agentStatusEpoch + 1, sortEpoch: s.sortEpoch + 1 }
          : {}),
        runtimeAgentOrchestrationByPaneKey: movePaneKeyedRecord(
          s.runtimeAgentOrchestrationByPaneKey,
          from,
          to
        ),
        retainedAgentsByPaneKey: movePaneKeyedRecord(
          s.retainedAgentsByPaneKey,
          from,
          to,
          (retained) => ({
            ...retained,
            entry: { ...retained.entry, paneKey: to, tabId: targetTabId },
            tab: targetTabId ? { ...retained.tab, id: targetTabId } : retained.tab
          })
        ),
        sleepingAgentSessionsByPaneKey: movePaneKeyedRecord(
          s.sleepingAgentSessionsByPaneKey,
          from,
          to,
          (record) => ({ ...record, paneKey: to, tabId: targetTabId })
        ),
        agentLaunchConfigByPaneKey: movePaneKeyedRecord(
          s.agentLaunchConfigByPaneKey,
          from,
          to,
          (entry) => ({
            ...entry,
            identity: { ...entry.identity, tabId: targetTabId, leafId: targetLeafId }
          })
        ),
        acknowledgedAgentsByPaneKey: movePaneKeyedRecord(s.acknowledgedAgentsByPaneKey, from, to),
        activityClearedAtByPaneKey: movePaneKeyedRecord(s.activityClearedAtByPaneKey, from, to),
        manuallyUnreadTurnsByPaneKey: movePaneKeyedRecord(s.manuallyUnreadTurnsByPaneKey, from, to),
        paneForegroundAgentByPaneKey: movePaneKeyedRecord(s.paneForegroundAgentByPaneKey, from, to),
        unreadTerminalPanes: movePaneKeyedRecord(s.unreadTerminalPanes, from, to),
        unreadAgentCompletionPanes: movePaneKeyedRecord(s.unreadAgentCompletionPanes, from, to),
        lastTerminalInputAtByPaneKey: movePaneKeyedRecord(s.lastTerminalInputAtByPaneKey, from, to),
        cacheTimerByKey: movePaneKeyedRecord(s.cacheTimerByKey, from, to),
        retentionSuppressedPaneKeys: movePaneKeyedRecord(s.retentionSuppressedPaneKeys, from, to)
      }))
      if (typeof window !== 'undefined') {
        window.api?.agentStatus?.transferPaneAuthority?.({
          fromPaneKey: from,
          toPaneKey: to,
          ...(transfer.ptyId ? { ptyId: transfer.ptyId } : {})
        })
      }
    }
  }
}

import { encodePowerShellCommand } from './powershell-command-encoding'
import { getPosixCodexShellLaunchPreflight } from './codex-shell-function'
import { getPosixClaudeShellFunction } from './claude-shell-function'
import {
  nativeWindowsPathToPosixShellPath,
  resolveSetupRunnerCommand,
  type SetupRunnerCommandPlatform,
  type SetupRunnerCommandShell,
  type SetupRunnerShell
} from './setup-runner-command'
import { createNonSecureContextUuid } from './non-secure-context-uuid'
import { quotePowerShellLiteral } from './powershell-native-argument'

const DEFAULT_WAIT_TIMEOUT_SECONDS = 2 * 60 * 60
// Exported so the gate and its tests share one definition.
export const SETUP_COMPLETE_MESSAGE = 'Setup finished; starting agent.'
export const SETUP_AGENT_SEQUENCE_STARTUP_COMMAND_ENV = 'ORCA_SEQUENCED_STARTUP_COMMAND'
export const SETUP_AGENT_SEQUENCE_STARTUP_SCRIPT_ENV = 'ORCA_SEQUENCED_STARTUP_SCRIPT'

export type SequencedSetupAgentCommands = {
  setupCommand: string
  startupCommand: string
  startupEnv?: Record<string, string>
}

export function resolveSetupAgentSequenceLaunchCommand(
  env: Record<string, string | undefined>,
  fallbackCommand: string | undefined
): string | undefined {
  const sequencedStartup = env[SETUP_AGENT_SEQUENCE_STARTUP_COMMAND_ENV]?.trim()
  return sequencedStartup || fallbackCommand
}

export function createSetupAgentSequenceNonce(): string {
  return createNonSecureContextUuid()
}

export function createSequencedSetupAgentCommands(args: {
  runnerScriptPath: string
  startupCommand: string
  platform: SetupRunnerCommandPlatform
  shell?: SetupRunnerShell
  nonce?: string
  waitTimeoutSeconds?: number
}): SequencedSetupAgentCommands {
  const nonce = args.nonce ?? createSetupAgentSequenceNonce()
  const resolution = resolveSetupRunnerCommand(args.runnerScriptPath, args.platform, args.shell)
  // Why: the gate is typed into the terminal pane and `startupCommand` is already quoted for that
  // pane, so a batch runner launched from a Git Bash pane still needs the bash gate — PowerShell's
  // `Invoke-Expression` cannot parse the POSIX `'\''` escaping the pane's quoting produces. The
  // runner itself still launches through `resolution.command`, never through bash.
  const posixGateForWindowsRunner = resolution.shell === 'windows' && args.shell?.family === 'posix'
  const markerBasePath = posixGateForWindowsRunner
    ? nativeWindowsPathToPosixShellPath(resolution.runnerScriptPathForShell)
    : resolution.runnerScriptPathForShell
  // Why: overlapping gated launches of the same setup runner must not race on
  // a shared completion marker.
  const markerPath = `${markerBasePath}.${nonce}.done`
  const waitTimeoutSeconds = args.waitTimeoutSeconds ?? DEFAULT_WAIT_TIMEOUT_SECONDS

  if (resolution.shell === 'windows' && !posixGateForWindowsRunner) {
    return {
      setupCommand: buildWindowsSetupCommand(
        resolution.runnerScriptPathForShell,
        markerPath,
        nonce
      ),
      startupCommand: buildWindowsStartupCommand(markerPath, nonce, waitTimeoutSeconds),
      startupEnv: {
        [SETUP_AGENT_SEQUENCE_STARTUP_COMMAND_ENV]: args.startupCommand
      }
    }
  }

  const startupScript = buildPosixStartupScript(
    args.startupCommand,
    markerPath,
    nonce,
    waitTimeoutSeconds
  )
  return {
    setupCommand: buildPosixSetupCommand(resolution.command, markerPath, nonce),
    // Why: long worktree paths can push the gate past a PTY's canonical input cap and drop its submit byte.
    startupCommand: `bash -lc 'eval "$${SETUP_AGENT_SEQUENCE_STARTUP_SCRIPT_ENV}"'`,
    startupEnv: {
      [SETUP_AGENT_SEQUENCE_STARTUP_COMMAND_ENV]: args.startupCommand,
      [SETUP_AGENT_SEQUENCE_STARTUP_SCRIPT_ENV]: startupScript
    }
  }
}

function buildPosixSetupCommand(setupCommand: string, markerPath: string, nonce: string): string {
  const marker = quotePosixArg(markerPath)
  const tmp = quotePosixArg(`${markerPath}.tmp`)
  const nonceValue = quotePosixArg(nonce)

  const script = [
    `rm -f ${marker} ${tmp} 2>/dev/null`,
    `( ${setupCommand} )`,
    'status=$?',
    `printf '%s:%s\\n' ${nonceValue} "$status" > ${tmp}`,
    `mv -f ${tmp} ${marker}`,
    'exit "$status"'
  ].join('; ')

  return `bash -lc ${quotePosixArg(script)}`
}

function buildPosixStartupScript(
  startupCommand: string,
  markerPath: string,
  nonce: string,
  waitTimeoutSeconds: number
): string {
  const marker = quotePosixArg(markerPath)
  const tmp = quotePosixArg(`${markerPath}.tmp`)
  const nonceValue = quotePosixArg(nonce)
  const timeout = Math.max(1, Math.floor(waitTimeoutSeconds))
  const startupSuccessCommand = buildPosixStartupSuccessCommand(startupCommand)
  // Why: the PTY launch path feeds this command through an interactive shell,
  // so keeping the wrapper on one line avoids visible `quote>` continuation
  // prompts while still preserving valid `while`/`if` shell syntax.
  const script = [
    `deadline=$((SECONDS + ${timeout}));`,
    'echo "Waiting for setup to finish before starting agent..." >&2;',
    'while :; do',
    `if [ -f ${marker} ]; then`,
    `IFS=: read -r seen status < ${marker} || true;`,
    `if [ "$seen" = ${nonceValue} ]; then`,
    `rm -f ${marker} ${tmp} 2>/dev/null;`,
    // Why: failure and timeout announce themselves; a silent success left
    // "Waiting for setup..." as the pane's last line forever.
    // Why here and not first: setup may be what puts codex on PATH, and this
    // `bash -lc` never reads Orca's shell wrapper, so it defines the function itself.
    `if [ "$status" = "0" ]; then echo ${quotePosixArg(SETUP_COMPLETE_MESSAGE)} >&2;\n${getPosixCodexShellLaunchPreflight() + getPosixClaudeShellFunction()}if [ -n "\${${SETUP_AGENT_SEQUENCE_STARTUP_COMMAND_ENV}:-}" ]; then eval "\$${SETUP_AGENT_SEQUENCE_STARTUP_COMMAND_ENV}"; exit "$?"; else ${startupSuccessCommand}; fi; fi;`,
    'echo "Setup failed; skipping agent startup." >&2;',
    'exit "${status:-1}";',
    'fi;',
    'fi;',
    'if [ "$SECONDS" -ge "$deadline" ]; then',
    'echo "Timed out waiting for setup before starting agent." >&2;',
    'exit 124;',
    'fi;',
    'sleep 1;',
    'done'
  ].join(' ')

  return script
}

function buildPosixStartupSuccessCommand(startupCommand: string): string {
  if (
    hasUnquotedPosixCommandSeparator(startupCommand) ||
    hasLeadingPosixEnvAssignment(startupCommand)
  ) {
    return `eval ${quotePosixArg(startupCommand)}; exit "$?"`
  }
  return `exec ${startupCommand}`
}

function hasLeadingPosixEnvAssignment(command: string): boolean {
  return /^[A-Za-z_][A-Za-z0-9_]*=/.test(command.trimStart())
}

function hasUnquotedPosixCommandSeparator(command: string): boolean {
  let quote: "'" | '"' | null = null
  let escaped = false
  for (const char of command) {
    if (escaped) {
      escaped = false
      continue
    }
    if (char === '\\') {
      escaped = true
      continue
    }
    if (quote) {
      if (char === quote) {
        quote = null
      }
      continue
    }
    if (char === "'" || char === '"') {
      quote = char
      continue
    }
    if (char === ';' || char === '&' || char === '|' || char === '\n' || char === '\r') {
      return true
    }
  }
  return false
}

function buildWindowsSetupCommand(
  runnerScriptPath: string,
  markerPath: string,
  nonce: string
): string {
  // Why: delayed expansion keeps path metacharacters as data when cmd invokes the batch runner.
  const script = [
    `$runner = ${quotePowerShellLiteral(runnerScriptPath)}`,
    `$marker = ${quotePowerShellLiteral(markerPath)}`,
    '$tmp = $marker + ".tmp"',
    `$nonce = ${quotePowerShellLiteral(nonce)}`,
    'Remove-Item -LiteralPath $marker, $tmp -Force -ErrorAction SilentlyContinue',
    '$processInfo = [System.Diagnostics.ProcessStartInfo]::new()',
    '$processInfo.FileName = $env:ComSpec',
    '$processInfo.Arguments = \'/d /s /v:on /c ""!ORCA_SETUP_RUNNER!""\'',
    '$processInfo.UseShellExecute = $false',
    '$processInfo.EnvironmentVariables["ORCA_SETUP_RUNNER"] = $runner',
    '$process = [System.Diagnostics.Process]::Start($processInfo)',
    '$process.WaitForExit()',
    '$setupStatus = $process.ExitCode',
    '$utf8 = [System.Text.UTF8Encoding]::new($false)',
    '[System.IO.File]::WriteAllText($tmp, ($nonce + ":" + $setupStatus + [Environment]::NewLine), $utf8)',
    'Move-Item -LiteralPath $tmp -Destination $marker -Force',
    'exit $setupStatus'
  ].join('; ')

  return encodePowerShellInvocation(script)
}

function buildWindowsStartupCommand(
  markerPath: string,
  nonce: string,
  waitTimeoutSeconds: number
): string {
  const timeout = Math.max(1, Math.floor(waitTimeoutSeconds))
  // Why: native Windows setup runners launch through cmd.exe, but PowerShell
  // gives us safe bounded file polling/parsing without a fragile batch label loop.
  const script = [
    // Why: the startup command is user-authored and may invoke a `.ps1`, which IS
    // execution-policy gated even though `-EncodedCommand` is not. This is the in-payload
    // stand-in for the `-ExecutionPolicy Bypass` switch dropped from the command line
    // (same trade as the agent-hooks launcher). Progress must be silenced first and
    // restored after: Set-ExecutionPolicy autoloads a module whose "Preparing modules for
    // first use." record would otherwise land on the stderr this gate writes to.
    //
    // The failure is reported rather than swallowed. Autoload can fail for reasons that
    // have nothing to do with policy -- a 5.1 install with duplicate extended type data
    // fails every cmdlet in Microsoft.PowerShell.Security -- and the old
    // `-ErrorAction SilentlyContinue` plus empty `catch` hid that completely, leaving the
    // user with an execution-policy refusal from their own script and no trace that the
    // relief had been attempted. `-ErrorAction Stop` is what routes a non-terminating
    // failure into the catch at all. Still never throws: a diagnostic is worth a line of
    // stderr, but not the startup this gate exists to run.
    "$orcaProgress = $ProgressPreference; $ProgressPreference = 'SilentlyContinue'",
    'try { Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force -ErrorAction Stop } ' +
      'catch { [Console]::Error.WriteLine("Orca: could not relax the execution policy for this " + ' +
      '"session (" + $_.FullyQualifiedErrorId + "). A startup command that runs a .ps1 " + ' +
      '"may be blocked.") }',
    '$ProgressPreference = $orcaProgress',
    `$marker = ${quotePowerShellLiteral(markerPath)}`,
    'if ([string]::IsNullOrWhiteSpace($marker)) {',
    '  [Console]::Error.WriteLine("Missing setup marker path.")',
    '  exit 1',
    '}',
    '$tmp = $marker + ".tmp"',
    `$nonce = ${quotePowerShellLiteral(nonce)}`,
    `$deadline = (Get-Date).AddSeconds(${timeout})`,
    '[Console]::Error.WriteLine("Waiting for setup to finish before starting agent...")',
    'while ($true) {',
    '  if (Test-Path -LiteralPath $marker) {',
    '    $content = Get-Content -LiteralPath $marker -TotalCount 1',
    '    if ($content -match "^([0-9A-Za-z_-]+):([0-9]+)$" -and $Matches[1] -eq $nonce) {',
    '      $setupStatus = [int]$Matches[2]',
    '      Remove-Item -LiteralPath $marker, $tmp -Force -ErrorAction SilentlyContinue',
    '      if ($setupStatus -ne 0) {',
    '        [Console]::Error.WriteLine("Setup failed; skipping agent startup.")',
    '        exit $setupStatus',
    '      }',
    `      $startup = $env:${SETUP_AGENT_SEQUENCE_STARTUP_COMMAND_ENV}`,
    '      if ([string]::IsNullOrWhiteSpace($startup)) {',
    '        [Console]::Error.WriteLine("Missing sequenced startup command.")',
    '        exit 1',
    '      }',
    `      [Console]::Error.WriteLine(${quotePowerShellLiteral(SETUP_COMPLETE_MESSAGE)})`,
    '      Invoke-Expression $startup',
    '      if ($global:LASTEXITCODE -ne $null) { exit $global:LASTEXITCODE }',
    '      if (-not $?) { exit 1 }',
    '      exit 0',
    '    }',
    '  }',
    '  if ((Get-Date) -ge $deadline) {',
    '    [Console]::Error.WriteLine("Timed out waiting for setup before starting agent.")',
    '    exit 124',
    '  }',
    '  Start-Sleep -Seconds 1',
    '}'
  ].join('; ')

  return encodePowerShellInvocation(script)
}

// Why: `-EncodedCommand` is not execution-policy gated (only `-File` is), so `-ExecutionPolicy
// Bypass` was a no-op — and it is one of the most heavily EDR-flagged PowerShell tokens. The
// base64 stays: these strings are typed into a terminal pane and re-parsed by its shell.
function encodePowerShellInvocation(script: string): string {
  return `powershell.exe -NoProfile -NonInteractive -EncodedCommand ${encodePowerShellCommand(script)}`
}

function quotePosixArg(value: string): string {
  if (/^[A-Za-z0-9_./:-]+$/.test(value)) {
    return value
  }
  return `'${value.replace(/'/g, `'\\''`)}'`
}

export function getSetupAgentSequenceShellForTests(
  runnerScriptPath: string,
  platform: SetupRunnerCommandPlatform
): SetupRunnerCommandShell {
  return resolveSetupRunnerCommand(runnerScriptPath, platform).shell
}

import type {
  BrowserClientHostedPageInventory,
  BrowserClientHostCommandEvent,
  BrowserClientHostCommandResult
} from '../../shared/browser-client-host-protocol'
import { assertBrowserHostPageCommandAdmission } from './browser-host-page-command-admission'
import type { BrowserHostLeaseState } from './browser-host-lease-records'
import type {
  BrowserClientPagePlacementReservation,
  BrowserHostPagePlacementRegistry,
  RuntimeBrowserPlacement
} from './browser-host-page-placement'
import type { BrowserHostPageReconciliationActions as ActionHandlers } from './browser-host-page-reconciliation-executor'
import type {
  BrowserHostPageReconciliationPlan,
  BrowserHostRuntimePageIntent
} from './browser-host-page-reconciliation-plan'

export class BrowserHostPageReconciliationActions {
  readonly controller = new AbortController()
  readonly handlers: ActionHandlers
  private readonly reservations = new Map<string, BrowserClientPagePlacementReservation>()
  private readonly closePlacements = new Map<string, RuntimeBrowserPlacement | undefined>()

  constructor(
    private readonly state: BrowserHostLeaseState,
    private readonly placements: BrowserHostPagePlacementRegistry,
    private readonly plan: BrowserHostPageReconciliationPlan
  ) {
    for (const page of [
      ...this.plan.close,
      ...this.plan.closeThenRestore.map(({ page }) => page)
    ]) {
      this.closePlacements.set(page.browserPageId, this.placements.getPlacement(page.browserPageId))
    }
    this.reserveTargetPlacements()
    this.handlers = {
      reclaimPage: (pair, signal) => this.reclaimPage(pair, signal),
      closePage: (page, signal) => this.closePage(page, signal),
      restorePage: (intent, signal) => this.restorePage(intent, signal)
    }
  }

  cancelReservations(): void {
    for (const reservation of this.reservations.values()) {
      this.placements.cancelClientPageReservation(reservation)
    }
  }

  private reserveTargetPlacements(): void {
    const targets = [
      ...this.plan.reclaim.map(({ intent }) => intent),
      ...this.plan.restore,
      ...this.plan.closeThenRestore.map(({ intent }) => intent)
    ].toSorted((left, right) => left.pageHostGeneration - right.pageHostGeneration)
    try {
      for (const intent of targets) {
        const reservation = this.placements.reserveClientPage(
          intent.browserPageId,
          {
            browserHostClientId: this.state.lease.browserHostClientId,
            browserHostGeneration: this.state.lease.browserHostGeneration
          },
          intent.pageHostGeneration
        )
        this.reservations.set(intent.browserPageId, reservation)
      }
    } catch (error) {
      this.cancelReservations()
      throw error
    }
  }

  private async reclaimPage(
    pair: BrowserHostPageReconciliationPlan['reclaim'][number],
    signal: AbortSignal
  ): Promise<void> {
    await this.issueCommand(
      pair.intent.browserPageId,
      pair.intent.pageHostGeneration,
      {
        type: 'reclaimPage',
        previousAuthority: pageAuthority(pair.page),
        browserProfileId: pair.intent.browserProfileId,
        executionHostKey: pair.intent.executionHostKey,
        ...(pair.intent.workspaceId ? { workspaceId: pair.intent.workspaceId } : {})
      },
      signal
    )
    this.commitReservation(pair.intent.browserPageId)
  }

  private async closePage(
    page: BrowserClientHostedPageInventory,
    signal: AbortSignal
  ): Promise<void> {
    await this.issueCommand(
      page.browserPageId,
      page.pageHostGeneration,
      { type: 'closePage', targetAuthority: pageAuthority(page) },
      signal
    )
    const placement = this.closePlacements.get(page.browserPageId)
    if (!placement) {
      return
    }
    if (this.placements.getPlacement(page.browserPageId) !== placement) {
      throw new Error('browser_page_placement_stale')
    }
    const retirement = this.placements.beginPageRetirement(page.browserPageId, placement)
    this.placements.completePageRetirement(retirement)
  }

  private async restorePage(
    intent: BrowserHostRuntimePageIntent,
    signal: AbortSignal
  ): Promise<void> {
    const url = this.plan.closeThenRestore.find(
      (pair) => pair.intent.browserPageId === intent.browserPageId
    )?.page.currentUrl
    await this.issueCommand(
      intent.browserPageId,
      intent.pageHostGeneration,
      {
        type: 'restorePage',
        browserProfileId: intent.browserProfileId,
        executionHostKey: intent.executionHostKey,
        ...(url ? { url } : {}),
        ...(intent.workspaceId ? { workspaceId: intent.workspaceId } : {})
      },
      signal
    )
    this.commitReservation(intent.browserPageId)
  }

  private async issueCommand(
    browserPageId: string,
    pageHostGeneration: number,
    command: BrowserClientHostCommandEvent['command'],
    signal: AbortSignal
  ): Promise<void> {
    assertNotAborted(signal)
    assertBrowserHostPageCommandAdmission(this.state.lease, command, (executionHostKey) =>
      this.state.executionHostGrants.require(executionHostKey)
    )
    const ledger = this.state.commandLedger
    if (!ledger) {
      throw new Error('browser_host_command_protocol_required')
    }
    const issued = ledger.issue({
      browserPageId,
      pageHostGeneration,
      command,
      resultAdmission: 'reconciliation'
    })
    const result = await waitForCommandResult(issued.result, signal)
    if (result.status === 'failed') {
      throw new Error(result.errorCode)
    }
    assertNotAborted(signal)
  }

  private commitReservation(browserPageId: string): void {
    const reservation = this.reservations.get(browserPageId)
    if (!reservation) {
      throw new Error('browser_page_reconciliation_reservation_required')
    }
    this.placements.commitClientPageReservation(reservation)
    this.reservations.delete(browserPageId)
  }
}

function pageAuthority(page: BrowserClientHostedPageInventory) {
  return {
    authorityRuntimeId: page.authorityRuntimeId,
    authorityEpoch: page.authorityEpoch,
    browserHostClientId: page.browserHostClientId,
    browserHostGeneration: page.browserHostGeneration,
    pageHostGeneration: page.pageHostGeneration
  }
}

function assertNotAborted(signal: AbortSignal): void {
  if (signal.aborted) {
    throw new Error('browser_host_page_reconciliation_aborted', { cause: signal.reason })
  }
}

async function waitForCommandResult(
  result: Promise<BrowserClientHostCommandResult>,
  signal: AbortSignal
): Promise<BrowserClientHostCommandResult> {
  let removeAbort = (): void => {}
  const aborted = new Promise<never>((_resolve, reject) => {
    const abort = (): void =>
      reject(new Error('browser_host_page_reconciliation_aborted', { cause: signal.reason }))
    if (signal.aborted) {
      abort()
      return
    }
    signal.addEventListener('abort', abort, { once: true })
    removeAbort = () => signal.removeEventListener('abort', abort)
  })
  try {
    return await Promise.race([result, aborted])
  } finally {
    removeAbort()
  }
}

name: Clean closed PR work

on:
  pull_request_target:
    types: [closed]

permissions:
  actions: write
  pull-requests: read

jobs:
  clean:
    runs-on: ubuntu-latest
    timeout-minutes: 5
    steps:
      - name: Cancel checks for an unmerged closed PR
        if: github.event.pull_request.merged == false
        uses: actions/github-script@v8
        with:
          script: |
            const closed = context.payload.pull_request
            const targets = [
              ['pr-checks', 'pr.yml'],
              ['node-server', 'node-server-tests.yml'],
              ['ssh-windows-hosts', 'ssh-windows-hosts.yml'],
              ['ssh-hostile-hosts', 'ssh-hostile-hosts.yml'],
              ['mobile', 'mobile.yml'],
              ['computer-e2e', 'computer-e2e.yml']
            ]
            const stillClosed = async () => {
              const { data: current } = await github.rest.pulls.get({
                ...context.repo, pull_number: closed.number
              })
              return current.state === 'closed' && current.merged_at === null &&
                current.closed_at === closed.closed_at
            }
            if (!Number.isSafeInteger(closed.number) || closed.number <= 0 ||
                !Number.isFinite(Date.parse(closed.closed_at))) {
              throw new Error('Missing closed PR identity')
            }
            if (!await stillClosed()) return
            for (const [prefix, workflow] of targets) {
              const group = `${prefix}-${closed.number}`
              let data
              try {
                const response = await github.request(
                  'GET /repos/{owner}/{repo}/actions/concurrency_groups/{concurrency_group_name}', {
                    ...context.repo, concurrency_group_name: group,
                    headers: { 'X-GitHub-Api-Version': '2026-03-10' }
                  }
                )
                data = response.data
              } catch (error) {
                if (error.status === 404) continue
                throw error
              }
              if (data.group_name !== group || !Array.isArray(data.group_members)) {
                throw new Error(`Unexpected concurrency group: ${group}`)
              }
              for (const member of data.group_members) {
                // Only whole PR runs; release/manual jobs never share this identity.
                if (member.job_id !== undefined || !Number.isSafeInteger(member.run_id)) continue
                const { data: run } = await github.rest.actions.getWorkflowRun({
                  ...context.repo, run_id: member.run_id
                })
                if (run.event !== 'pull_request' || run.path !== `.github/workflows/${workflow}` ||
                    run.status === 'completed' ||
                    !Number.isFinite(Date.parse(run.created_at)) ||
                    Date.parse(run.created_at) > Date.parse(closed.closed_at)) continue
                if (!await stillClosed()) return
                try {
                  await github.rest.actions.cancelWorkflowRun({
                    ...context.repo, run_id: member.run_id
                  })
                  core.info(`Requested cancellation of ${group}: ${member.run_id}`)
                } catch (error) {
                  if (error.status !== 409) throw error
                }
              }
            }
      # No checkout: this runs trusted default-branch code, including for fork PRs.
      - uses: actions/github-script@v8
        if: '!cancelled()'
        with:
          script: |
            const ref = `refs/pull/${context.payload.pull_request.number}/merge`
            const caches = await github.paginate(github.rest.actions.getActionsCacheList, {
              ...context.repo, ref, per_page: 100
            })
            for (const cache of caches) {
              if (cache.ref !== ref) throw new Error(`Unexpected cache ref: ${cache.ref}`)
              try {
                await github.rest.actions.deleteActionsCacheById({
                  ...context.repo, cache_id: cache.id
                })
              } catch (error) {
                if (error.status !== 404) throw error
              }
            }
            core.info(`Removed ${caches.length} caches scoped to ${ref}`)

